//! @file
//! @brief Helper utility functions to support the `omni.observability.core` library.
#pragma once

#include <stdint.h>


// ********************************** Platform Helper Macros **************************************
/** Helper macro to help in notifying of code locations that need to be reimplemented for new
 *  platforms.  This will always generate a compile error due to a failed static assert.
 */
#define OMNI_OTEL_UNSUPPORTED_PLATFORM() static_assert(false, "Unsupported platform!")


// ****** Platform Identification Macros ******
#ifdef DOXYGEN_BUILD
/** A macro defined to `1` when the current target platform is Linux.  This will be set to
 *  `0` for non-Linux platforms.
 */
#    define OMNI_OTEL_PLATFORM_LINUX 0

/** A macro defined to `1` when the current target platform is Windows.  This will be set
 *  to `0` for non-Windows platforms.
 */
#    define OMNI_OTEL_PLATFORM_WINDOWS 1
#else
#    ifdef _WIN32
#        define OMNI_OTEL_PLATFORM_LINUX 0
#        define OMNI_OTEL_PLATFORM_WINDOWS 1
#    elif defined(__linux__)
#        define OMNI_OTEL_PLATFORM_LINUX 1
#        define OMNI_OTEL_PLATFORM_WINDOWS 0
#    endif
#endif


// ****** Compiler Identification Macros ******
#ifdef DOXYGEN_BUILD
/** Macro that is set to `1` when the Microsoft C/C++ toolchain is being used to build the
 *  project.  This will be set to `0` when using a different toolchain.
 */
#    define OMNI_OTEL_COMPILER_MSC 0

/** Macro that is set to `1` when a GNU C compatible toolchain is being used to build the
 *  project.  This will include GCC/G++ and Clang.  This will be set to `0` when using a
 *  different toolchain.
 */
#    define OMNI_OTEL_COMPILER_GNUC 1
#elif defined(OMNI_OTEL_COMPILER_MSC) && defined(OMNI_OTEL_COMPILER_GNUC)
#    if (!!OMNI_OTEL_COMPILER_MSC) + (!!OMNI_OTEL_COMPILER_GNUC) != 1
#        define OMNI_OTEL_COMPILER_MSC // Show previous definition
#        define OMNI_OTEL_COMPILER_GNUC // Show previous definition
#        error Exactly one of OMNI_OTEL_COMPILER_MSC or OMNI_OTEL_COMPILER_GNUC must be non-zero.
#    endif
#elif !defined(OMNI_OTEL_COMPILER_MSC) && !defined(OMNI_OTEL_COMPILER_GNUC)
#    ifndef OMNI_OTEL_COMPILER_MSC
#        if defined(_MSC_VER)
#            define OMNI_OTEL_COMPILER_MSC 1
#            define OMNI_OTEL_COMPILER_GNUC 0
#        elif defined(__GNUC__)
#            define OMNI_OTEL_COMPILER_MSC 0
#            define OMNI_OTEL_COMPILER_GNUC 1
#        else
#            error "Unsupported compiler."
#        endif
#    endif
#else
#    error "Must define OMNI_OTEL_COMPILER_MSC and OMNI_OTEL_COMPILER_GNUC or neither."
#endif

#ifdef DOXYGEN_BUILD
/** Macro that is set to `1` when the Clang toolchain is being used to build the project.  Note
 *  that @ref OMNI_OTEL_COMPILER_GNUC will also be set to `1` in this case since Clang is also
 *  a GCC/G++ compatible toolchain.  This will be set to `0` when using a non-Clang toolchain.
 */
#    define OMNI_OTEL_TOOLCHAIN_CLANG 0
#elif !defined(OMNI_OTEL_TOOLCHAIN_CLANG)
#    if defined(__clang__)
#        define OMNI_OTEL_TOOLCHAIN_CLANG 1
#    else
#        define OMNI_OTEL_TOOLCHAIN_CLANG 0
#    endif
#endif


// ****** Symbol Export and Compiler Helper Macros ******
#ifndef OMNI_OTEL_DEBUG
#    if defined(NDEBUG) || defined(DOXYGEN_BUILD)
/** A macro indicating whether the current compilation unit is built in debug mode. Always defined
 *  as either 0 or 1. Can be overridden by defining before this file is included or by passing on
 *  the compiler command line. Defined as `0` if `NDEBUG` is defined; `1` otherwise.
 */
#        define OMNI_OTEL_DEBUG 0
#    else
#        define OMNI_OTEL_DEBUG 1
#    endif
#endif

#if defined(__cplusplus) || defined(DOXYGEN_BUILD)
/** Macro to define a symbol that is exported with a C decoration instead of C++. */
#    define OMNI_OTEL_EXTERN_C extern "C"
#endif

/** Macro to tag that a symbol should expect to be imported from another module. */
#define OMNI_OTEL_IMPORT OMNI_OTEL_EXTERN_C

#ifdef DOXYGEN_BUILD
/** Macro to allow a compiler specific attribute to be added to a symbol.  This will resolve to
 *  nothing when using the Microsoft C/C++ toolchain, but will be `__attribute__((...))` on GNU
 *  C/C++ compatible toolchains (ie: GCC/G++, Clang).
 */
#    define OMNI_OTEL_ATTRIBUTE(...)

/** Macro to provide a `__declspec(...)` tag to a symbol.  This will resolve to nothing on a
 *  non-Microsoft C/C++ toolchain.
 */
#    define OMNI_OTEL_DECLSPEC(...)
#else
#    if OMNI_OTEL_COMPILER_MSC
#        if OMNI_OTEL_TOOLCHAIN_CLANG
#            define OMNI_OTEL_ATTRIBUTE(...) __attribute__((__VA_ARGS__))
#        else
#            define OMNI_OTEL_ATTRIBUTE(...)
#        endif
#        define OMNI_OTEL_DECLSPEC(...) __declspec(__VA_ARGS__)
#    elif OMNI_OTEL_COMPILER_GNUC
#        define OMNI_OTEL_ATTRIBUTE(...) __attribute__((__VA_ARGS__))
#        define OMNI_OTEL_DECLSPEC(...)
#    endif
#endif

/** Macro to unconditionally export a symbol from a given module.  This can be used to export
 *  symbols from libraries.
 */
#define OMNI_OTEL_EXPORT OMNI_OTEL_EXTERN_C OMNI_OTEL_DECLSPEC(dllexport) OMNI_OTEL_ATTRIBUTE(visibility("default"))

#if defined(OMNI_OTEL_EXPORTS) || defined(DOXYGEN_BUILD)
/** Macro to export or import a symbol from a given module.  If the `OMNI_OTEL_EXPORTS` macro
 *  is defined, the symbol will be exported from the module.  In this case, this macro must only
 *  be defined in a single translation unit in the module otherwise there will be multiple
 *  definition linking errors.  If `OMNI_OTEL_EXPORTS` is not defined, the module will be
 *  expecting to import the symbol from another module or library.
 */
#    define OMNI_OTEL_DYNAMICLINK OMNI_OTEL_EXPORT
#else
#    define OMNI_OTEL_DYNAMICLINK OMNI_OTEL_IMPORT
#endif


// ********************************** General Helper Macros ***************************************
/** Calculates the number of items in an array. */
#define OMNI_COUNTOF(x) (sizeof(x) / sizeof((x)[0]))


// ************************************* Logging Helpers ******************************************
/** Main Omniverse namespace. */
namespace omni
{
/** Namespace for observability functionality. */
namespace observability
{

/** An identifier of a single registered logger.  This ID can be reused if a logger is
 *  unregistered and a new one is registered in its place.  It is the caller's responsiblity
 *  to ensure a logger ID is cleared out once it is unregistered.
 */
using LoggerId = int64_t;

/** The identifier of an invalid logger. */
constexpr LoggerId kInvalidLoggerId = -1;

/** A unique identifier for a process.  This ID is provided by the OS. */
using ProcessId = int64_t;

/** A unique identifier for a thread.  This ID is provided by the OS. */
using ThreadId = int64_t;

/** Format specifier for printf() style format strings for a thread ID value. */
#define PRI_ThreadId PRId64

/** Format specifier for printf() style format strings for a process ID value. */
#define PRI_ProcessId PRId64

} // namespace observability
} // namespace omni
